        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().isLazyLoadingEnabled()).isFalse();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDefaultStatementTimeout()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDefaultFetchSize()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getLocalCacheScope()).isEqualTo(LocalCacheScope.SESSION);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getJdbcTypeForNull()).isEqualTo(JdbcType.OTHER);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDefaultResultSetType()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDefaultExecutorType()).isEqualTo(ExecutorType.SIMPLE);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getAutoMappingBehavior()).isEqualTo(AutoMappingBehavior.PARTIAL);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getAutoMappingUnknownColumnBehavior()).isEqualTo(AutoMappingUnknownColumnBehavior.NONE);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getLogPrefix()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getLazyLoadTriggerMethods()).isEqualTo(new HashSet<>(Arrays.asList("equals", "clone", "hashCode", "toString")));
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getLogImpl()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getVfsImpl()).isEqualTo(SpringBootVFS.class);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDefaultSqlProviderType()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getTypeHandlerRegistry().getTypeHandler(JdbcType.class).getClass()).isEqualTo(EnumTypeHandler.class);
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getConfigurationFactory()).isNull();
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getVariables()).hasToString("{}");
        assertThat(context.getBean(SqlSessionFactory.class).getConfiguration().getDatabaseId()).isNull();
    });
}
