        BoundSql boundSql = sqlSource.getBoundSql(params);
        assertThat(boundSql.getSql()).isEqualTo("SELECT CURRENT_TIMESTAMP");
        VelocityLanguageDriverConfig config = context.getBean(VelocityLanguageDriverConfig.class);
