        assertThat(config.getAdditionalContextAttributes()).hasSize(2);
        assertThat(config.getAdditionalContextAttributes()).containsEntry("attribute1", "java.lang.String");
        assertThat(config.getAdditionalContextAttributes()).containsEntry("attribute2", "java.util.HashMap");
        assertThat(config.getVelocitySettings()).hasSize(3);
        assertThat(config.getVelocitySettings()).containsEntry(RuntimeConstants.RESOURCE_LOADERS, "class");
        assertThat(config.getVelocitySettings()).containsEntry(RuntimeConstants.RESOURCE_LOADER + ".class.class", "org.apache.velocity.runtime.resource.loader.ClasspathResourceLoader");
        assertThat(config.generateCustomDirectivesString()).isEqualTo(NowDirective.class.getName() + ",org.mybatis.scripting.velocity.TrimDirective,org.mybatis.scripting.velocity.WhereDirective,org.mybatis.scripting.velocity.SetDirective,org.mybatis.scripting.velocity.InDirective,org.mybatis.scripting.velocity.RepeatDirective");
        assertThat(config.getVelocitySettings()).containsEntry(RuntimeConstants.INPUT_ENCODING, RuntimeConstants.ENCODING_DEFAULT);
    });
}
